internal fun schemeFor(
    seed: SeedColor,
    mode: ThemeMode,
): ColorScheme =
    when (seed) {
        SeedColor.Indigo -> {
            when (mode) {
                ThemeMode.Light -> indigoLight
                ThemeMode.Dark -> indigoDark
                ThemeMode.Oled -> indigoOled
            }
        }

        SeedColor.Teal -> {
            when (mode) {
                ThemeMode.Light -> tealLight
                ThemeMode.Dark -> tealDark
                ThemeMode.Oled -> tealOled
            }
        }

        SeedColor.Amber -> {
            when (mode) {
                ThemeMode.Light -> amberLight
                ThemeMode.Dark -> amberDark
                ThemeMode.Oled -> amberOled
            }
        }

        SeedColor.Rose -> {
            when (mode) {
                ThemeMode.Light -> roseLight
                ThemeMode.Dark -> roseDark
                ThemeMode.Oled -> roseOled
            }
        }

        SeedColor.Green -> {
            when (mode) {
                ThemeMode.Light -> greenLight
                ThemeMode.Dark -> greenDark
                ThemeMode.Oled -> greenOled
            }
        }

        SeedColor.Graphite -> {
            when (mode) {
                ThemeMode.Light -> graphiteLight
                ThemeMode.Dark -> graphiteDark
                ThemeMode.Oled -> graphiteOled
            }
        }
    }

/** Power key colors: fixed red family, NOT derived from the seed so Power always reads as Power. */
internal val PowerColorsLight = PowerColors(Color(0xFFB5242F), Color(0xFFFFFFFF), Color(0xFFFFDAD8), Color(0xFF410006))
internal val PowerColorsDark = PowerColors(Color(0xFFFFB3B0), Color(0xFF68000F), Color(0xFF92011A), Color(0xFFFFDAD8))
